// App-shell service worker for the whole site (homepage + every media-type section).
//
// CACHE_NAME is a hash of the deployed shell files, auto-generated by Source/build.py on
// every run -- never hand-edit it here. activate() deletes any previously-cached version
// under a different name, so this hash changing is what actually invalidates stale
// copies after a deploy; if you edit this file directly, build.py will overwrite this
// line the next time it runs anyway.
const CACHE_NAME = 'the-backlog-shell-658e8720d632';

// Cover images (docs/games/covers/<content hash>.jpg) live in their own cache that
// survives deploys: their names are content hashes, so a cached file can never go stale,
// and re-downloading ~2,000 covers on every CACHE_NAME bump would waste phone data.
const COVERS_CACHE = 'the-backlog-covers-v1';

const SHELL_ASSETS = [
  '/the-backlog/',
  '/the-backlog/index.html',
  '/the-backlog/games/',
  '/the-backlog/games/index.html',
  '/the-backlog/shared/base.css',
  '/the-backlog/shared/firebase-init.js',
  '/the-backlog/shared/pull-to-refresh.js',
  '/the-backlog/shared/nav.js',
  '/the-backlog/manifest.json',
  '/the-backlog/icons/icon-192.png',
  '/the-backlog/icons/icon-512.png',
];

self.addEventListener('install', function (event) {
  event.waitUntil(
    caches.open(CACHE_NAME).then(function (cache) {
      // cache: 'reload' skips the browser's HTTP cache (GitHub Pages serves max-age=600),
      // so a fresh install can't lock in a stale base.css/nav.js until the next deploy.
      return cache.addAll(SHELL_ASSETS.map(function (u) { return new Request(u, { cache: 'reload' }); }));
    }).then(function () {
      return self.skipWaiting();
    })
  );
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys().then(function (names) {
      return Promise.all(
        names.filter(function (name) { return name !== CACHE_NAME && name !== COVERS_CACHE; })
          .map(function (name) { return caches.delete(name); })
      );
    }).then(function () {
      return self.clients.claim();
    })
  );
});

// Firebase Auth/Firestore calls and the Google Fonts stylesheet/font files are cross-origin
// and deliberately left alone here so they always hit the network (or fail visibly offline)
// rather than ever being served stale from this cache.
self.addEventListener('fetch', function (event) {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Page navigations (loading games/index.html or index.html itself) always try the
  // network first. Cache-first here was the actual cause of deploys not showing up: the
  // service worker's own update+activate+reload cycle only runs on certain navigations, so
  // a tab or installed PWA instance left open since before a deploy could keep serving the
  // old cached page indefinitely with nothing left to trigger a recheck. Network-first means
  // a fresh deploy shows up on the very next load, independent of that cycle ever having
  // run -- the cache here now exists purely as an offline fallback, not a normal-case path.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).then(function (response) {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then(function (cache) { cache.put(request, copy); });
        }
        return response;
      }).catch(function () {
        return caches.match(
          url.pathname.startsWith('/the-backlog/games/')
            ? '/the-backlog/games/index.html'
            : '/the-backlog/index.html'
        );
      })
    );
    return;
  }

  // Covers, wherever they're served from: GitHub Pages while they still live in the repo,
  // or the worker's R2-backed /img/ route once they don't. Cross-origin image requests come
  // back opaque, which is fine to store and replay for an <img>, but an opaque response is
  // never `ok`, so it has to be cached on type instead.
  var isCover = url.pathname.startsWith('/the-backlog/games/covers/') ||
    (url.hostname === 'backlog-proxy.tlackey01.workers.dev' && url.pathname.startsWith('/img/'));
  if (isCover) {
    event.respondWith(
      caches.open(COVERS_CACHE).then(function (cache) {
        return cache.match(request).then(function (cached) {
          if (cached) return cached;
          return fetch(request).then(function (response) {
            if (response && (response.ok || response.type === 'opaque')) {
              cache.put(request, response.clone());
            }
            return response;
          });
        });
      })
    );
    return;
  }

  // Every other shell asset (CSS/JS/images) stays cache-first -- these are versioned by
  // CACHE_NAME above, so any real change already forces a new cache name and a genuine
  // network fetch during install; there's no staleness risk left to trade away here.
  event.respondWith(
    caches.match(request).then(function (cached) {
      if (cached) return cached;

      return fetch(request).then(function (response) {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then(function (cache) { cache.put(request, copy); });
        }
        return response;
      }).catch(function () {
        return Response.error();
      });
    })
  );
});
